const unbalancedLedgerTxns = `-- name: UnbalancedLedgerTxns :many
SELECT txn_id, sum(amount_minor) FILTER (WHERE direction = 'debit')::bigint AS debits,
       sum(amount_minor) FILTER (WHERE direction = 'credit')::bigint AS credits
FROM ledger_entries GROUP BY txn_id
HAVING coalesce(sum(amount_minor) FILTER (WHERE direction = 'debit'), 0) <> coalesce(sum(amount_minor) FILTER (WHERE direction = 'credit'), 0)
`

type UnbalancedLedgerTxnsRow struct {
	TxnID   uuid.UUID
	Debits  int64
	Credits int64
}

// tenant: system - the ledger's invariant check.
func (q *Queries) UnbalancedLedgerTxns(ctx context.Context) ([]UnbalancedLedgerTxnsRow, error) {
	rows, err := q.db.Query(ctx, unbalancedLedgerTxns)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []UnbalancedLedgerTxnsRow
	for rows.Next() {
		var i UnbalancedLedgerTxnsRow
		if err := rows.Scan(&i.TxnID, &i.Debits, &i.Credits); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

